// Browser side of asku: bind to the session, decrypt questions, render controls, send encrypted answers.
import "./style.css";
import DOMPurify from "dompurify";
import { marked } from "marked";
import { bindTag, checkFragment, deriveKeys, open, seal, type Keys } from "../src/crypto";
// @ts-ignore generated by build.ts
import { answer as validAnswer, question as validQuestion } from "./gen/validate.js";

type Option = string | { value: string; label?: string; md?: string };
type Item = {
  id: string; type: "confirm" | "single" | "multi" | "text" | "number"; label: string; md?: string; required?: boolean;
  options?: Option[]; default?: any; min?: number; max?: number; step?: number;
  placeholder?: string; multiline?: boolean; maxLength?: number;
};
type Question = { title?: string; md?: string; questions: Item[] };
type Answer = { answers: Record<string, unknown>; skipped: string[]; comments: Record<string, string>; note: string; error?: string };
type State = { priv: CryptoKey; pubA: string; key: string; answered: number[] };

const app = document.getElementById("app")!;

function h<K extends keyof HTMLElementTagNameMap>(tag: K, props: Partial<HTMLElementTagNameMap[K]> = {}, ...kids: (Node | string | null | undefined)[]) {
  const el = Object.assign(document.createElement(tag), props);
  el.append(...kids.filter((k): k is Node | string => k != null));
  return el;
}

DOMPurify.addHook("afterSanitizeAttributes", (node) => {
  if (node.tagName === "A") { node.setAttribute("target", "_blank"); node.setAttribute("rel", "noopener noreferrer"); }
});
function md(src: string) {
  const div = h("div", { className: "md" });
  div.innerHTML = DOMPurify.sanitize(marked.parse(src, { async: false }) as string);
  return div;
}

function status(text: string, kind: "info" | "error" | "done" = "info") {
  app.replaceChildren(h("p", { className: `status ${kind}`, textContent: text }));
}

// ---- persistence: the fragment is gone after first load, so key pair B and the write key live in IndexedDB.
// ponytail: IndexedDB unavailable (some private modes) means a reload loses the session; fine, the agent can start a new one.
const idb = new Promise<IDBDatabase>((resolve, reject) => {
  const r = indexedDB.open("asku", 1);
  r.onupgradeneeded = () => r.result.createObjectStore("s");
  r.onsuccess = () => resolve(r.result);
  r.onerror = () => reject(r.error);
});
async function db<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>) {
  const d = await idb;
  return new Promise<T>((resolve, reject) => {
    const r = fn(d.transaction("s", mode).objectStore("s"));
    r.onsuccess = () => resolve(r.result);
    r.onerror = () => reject(r.error);
  });
}
const load = (sid: string) => db<State | undefined>("readonly", (s) => s.get(sid)).catch(() => undefined);
const save = (sid: string, st: State) => db("readwrite", (s) => s.put(st, sid)).catch(() => {});
const drop = (sid: string) => db("readwrite", (s) => s.delete(sid)).catch(() => {});

const post = (path: string, body: unknown, key?: string) =>
  fetch(path, {
    method: "POST",
    headers: { "content-type": "application/json", ...(key ? { authorization: `Bearer ${key}` } : {}) },
    body: JSON.stringify(body),
  });

// ---- controls
const opt = (o: Option) => (typeof o === "string" ? { value: o, label: o, md: undefined } : { value: o.value, label: o.label ?? o.value, md: o.md });

function choice(type: "radio" | "checkbox", name: string, value: string, label: string, checked: boolean, detail?: string) {
  const input = h("input", { type, name, value, checked });
  return { input, el: h("label", { className: "opt" }, input, h("span", {}, label, detail ? md(detail) : null)) };
}

function field(it: Item) {
  const box = h("fieldset", { className: "q" },
    h("legend", {}, it.label, it.required ? h("span", { className: "req", textContent: " *", title: "required" }) : null),
    it.md ? md(it.md) : null);
  const name = `f-${it.id}`;
  let value: () => unknown;
  let check = (): string | null => null;

  switch (it.type) {
    case "confirm": {
      const yes = choice("radio", name, "yes", "Yes", it.default === true);
      const no = choice("radio", name, "no", "No", it.default === false);
      box.append(h("div", { className: "row" }, yes.el, no.el));
      value = () => (yes.input.checked ? true : no.input.checked ? false : undefined);
      break;
    }
    case "single":
    case "multi": {
      const multi = it.type === "multi";
      const def = new Set<string>(multi ? it.default ?? [] : it.default !== undefined ? [it.default] : []);
      const cs = it.options!.map(opt).map((o) => choice(multi ? "checkbox" : "radio", name, o.value, o.label, def.has(o.value), o.md));
      box.append(...cs.map((c) => c.el));
      const picked = () => cs.filter((c) => c.input.checked).map((c) => c.input.value);
      value = () => (multi ? (picked().length ? picked() : undefined) : picked()[0]);
      if (multi) check = () => {
        const n = picked().length;
        if (n && it.min !== undefined && n < it.min) return `pick at least ${it.min}`;
        if (it.max !== undefined && n > it.max) return `pick at most ${it.max}`;
        return null;
      };
      break;
    }
    case "text": {
      const el = it.multiline ? h("textarea", { rows: 4 }) : h("input", { type: "text" });
      Object.assign(el, { placeholder: it.placeholder ?? "", value: it.default ?? "" });
      if (it.maxLength) el.maxLength = it.maxLength;
      box.append(el);
      value = () => (el.value.trim() ? el.value : undefined);
      break;
    }
    case "number": {
      const el = h("input", { type: "number", inputMode: "decimal", value: it.default !== undefined ? String(it.default) : "" });
      if (it.min !== undefined) el.min = String(it.min);
      if (it.max !== undefined) el.max = String(it.max);
      el.step = it.step !== undefined ? String(it.step) : "any";
      box.append(el);
      value = () => (el.value === "" ? undefined : el.valueAsNumber);
      check = () => (el.validity.valid ? null : el.validationMessage || "not a valid number");
      break;
    }
  }

  const comment = h("textarea", { rows: 2, placeholder: "Comment for the agent (optional)" });
  box.append(h("details", { className: "comment" }, h("summary", { textContent: "Add a comment" }), comment));
  return { it, el: box, value: value!, check, comment };
}

// ---- session
async function send(sid: string, keys: Keys, st: State, seq: number, a: Answer) {
  const res = await post(`/s/${sid}/a`, await seal(keys, sid, "a", seq, JSON.stringify(a)), st.key);
  if (res.status !== 204 && res.status !== 409) throw new Error(`relay said ${res.status}`); // 409: already answered
  st.answered.push(seq);
  await save(sid, st);
}

function render(sid: string, keys: Keys, st: State, seq: number, q: Question) {
  const fields = q.questions.map(field);
  const note = h("textarea", { rows: 2, placeholder: "Anything else for the agent? (optional)" });
  const err = h("p", { className: "error", role: "alert" });
  const btn = h("button", { type: "submit", textContent: "Send" });
  const form = h("form", { className: "card", noValidate: true },
    q.title ? h("h1", { textContent: q.title }) : null,
    q.md ? md(q.md) : null,
    ...fields.map((f) => f.el),
    h("label", { className: "note" }, "Note", note),
    err, btn);

  form.onsubmit = async (e) => {
    e.preventDefault();
    const a: Answer = { answers: {}, skipped: [], comments: {}, note: note.value.trim() };
    const problems: string[] = [];
    for (const f of fields) {
      const v = f.value();
      const bad = v === undefined ? (f.it.required ? "required" : null) : f.check();
      f.el.classList.toggle("invalid", !!bad);
      if (bad) problems.push(`${f.it.label}: ${bad}`);
      else if (v === undefined) a.skipped.push(f.it.id);
      else a.answers[f.it.id] = v;
      if (f.comment.value.trim()) a.comments[f.it.id] = f.comment.value.trim();
    }
    if (problems.length) {
      err.textContent = problems.join(" · ");
      form.querySelector(".invalid")?.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    if (!validAnswer(a)) return (err.textContent = "Could not build a valid answer; please report this.");
    btn.disabled = true;
    btn.textContent = "Sending…";
    try {
      await send(sid, keys, st, seq, a);
      status("Sent. Waiting for the agent's next question…", "done");
    } catch (x) {
      err.textContent = `Not sent: ${(x as Error).message}. Try again.`;
      btn.disabled = false;
      btn.textContent = "Send";
    }
  };
  app.replaceChildren(form);
  if (document.hidden) document.title = "● asku: question waiting";
}

document.addEventListener("visibilitychange", () => { if (!document.hidden) document.title = "asku"; });

function listen(sid: string, keys: Keys, st: State) {
  status("Connected. Waiting for the agent's question…");
  const es = new EventSource(`/s/${sid}/q`);
  es.addEventListener("q", async (e) => {
    const seq = Number(e.lastEventId);
    if (st.answered.includes(seq)) return;
    let q: Question;
    try {
      q = JSON.parse(await open(keys, sid, "q", seq, JSON.parse(e.data)));
    } catch {
      return status("A message failed verification and was ignored. If this repeats, ask the agent for a new link.", "error");
    }
    if (!validQuestion(q)) {
      const detail = (validQuestion as any).errors?.map((x: any) => `${x.instancePath || "/"} ${x.message}`).join("; ");
      await send(sid, keys, st, seq, { answers: {}, skipped: [], comments: {}, note: "", error: `invalid question: ${detail}`.slice(0, 2000) }).catch(() => {});
      return status("The agent sent a question this page can't show. It has been told; wait for a corrected one.", "error");
    }
    render(sid, keys, st, seq, q);
  });
  es.addEventListener("close", () => {
    es.close();
    drop(sid);
    status("The agent ended this session. You can close this tab.", "done");
  });
  es.onerror = () => {
    if (es.readyState === EventSource.CLOSED) status("This session has ended or expired.", "error");
  };
}

async function main() {
  const m = location.pathname.match(/^\/a\/([\w-]{22})$/);
  if (!m) {
    app.replaceChildren(
      h("h1", { textContent: "asku" }),
      h("p", { textContent: "End-to-end encrypted questions from AI agents to you. Agents give you a link; open it here and answer." }));
    return;
  }
  const sid = m[1];
  const frag = location.hash.slice(1);
  if (frag) history.replaceState(null, "", location.pathname); // keep T out of history and screenshots

  let st = await load(sid);
  if (!st) {
    if (!frag) return status("This link is incomplete, or it was opened in another browser. Ask the agent for a new link.", "error");
    const res = await fetch(`/s/${sid}`);
    if (res.status === 404) return status("This session has ended or expired.", "error");
    const { pub, bound } = await res.json();
    if (bound) return status("This link was already opened in another browser or device. Continue there, or ask the agent for a new link.", "error");
    const pubA = Uint8Array.fromBase64(pub);
    let token: Uint8Array;
    try {
      token = await checkFragment(frag, pubA);
    } catch {
      return status("This link doesn't match its session. It may have been altered; ask the agent for a new link.", "error");
    }
    const kp = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);
    const pubB = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey));
    const b = await post(`/s/${sid}/bind`, { pub: pubB.toBase64(), mac: await bindTag(token, pubB) });
    if (b.status === 409) return status("This link was already opened in another browser or device. Continue there, or ask the agent for a new link.", "error");
    if (!b.ok) return status(`Could not join the session (${b.status}).`, "error");
    st = { priv: kp.privateKey, pubA: pub, key: (await b.json()).key, answered: [] };
    await save(sid, st);
  }
  listen(sid, await deriveKeys(st.priv, Uint8Array.fromBase64(st.pubA)), st);
}

main().catch((e) => status(`Something went wrong: ${e.message}`, "error"));
